type CycleRuleRevision={effective:number;cadence:'daily'|'weekly';weekdays:number[];endDay?:number}
type MainCycle={continueAfterGoal?:boolean;revisions?:CycleRuleRevision[];pausedAt?:number;endedAt?:number;pauses?:{from:number;to:number}[];pauseOffsets?:{index:number;days:number}[];id:string;goal:number;title:string;origin:string;index:number;qualified:number;cadence:'daily'|'weekly';weekdays:number[];endDay?:number;seedPlanned?:number;seedCompleted?:number}
type MainCycleReceipt={key:string;cycleId:string;title:string;start:string;end:string;planned:number;completed:number;rate:number|null;before:number;after:number;factor:number;nextFactor:number;xp:number}
