function cycleBounds(c:MainCycle,asOf:number){
 const shifts=(c.pauseOffsets||[]),past=shifts.filter(v=>v.index<c.index).reduce((n,v)=>n+v.days,0),all=shifts.filter(v=>v.index<=c.index).reduce((n,v)=>n+v.days,0);
 const ongoing=c.pausedAt===undefined?0:Math.max(0,Math.min(asOf,c.endedAt??asOf)-c.pausedAt);
 return {start:addDateDays(anchorMonth(c.origin,c.index),past),end:addDateDays(anchorMonth(c.origin,c.index+1),all+ongoing),pausedDays:all+ongoing};
}
function cycleRule(c:MainCycle,day:number){return [...(c.revisions||[])].reverse().find(r=>r.effective<=day)||{cadence:c.cadence,weekdays:c.weekdays,endDay:c.endDay}}
function cycleScheduledBase(c:MainCycle,day:number){return (c.endDay===undefined||day<=c.endDay)&&(c.cadence==='daily'||c.weekdays.includes(new Date(2026,9,18+day).getDay()))}
function cycleScheduled(c:MainCycle,day:number){const r=cycleRule(c,day);return (r.endDay===undefined||day<=r.endDay)&&(r.cadence==='daily'||r.weekdays.includes(new Date(2026,9,18+day).getDay()))}
function cyclePausedDay(c:MainCycle,day:number){return (c.pauses||[]).some(p=>day>=p.from&&day<p.to)||(c.pausedAt!==undefined&&day>=c.pausedAt)}
function mainCycleSnapshot(c:MainCycle,tasks:Task[],asOf=0){
 const {start,end}=cycleBounds(c,asOf),first=dayOf(start),last=dayOf(end);
 const plannedCount=(from:number,to:number,excludePause:boolean)=>Array.from({length:Math.max(0,to-from)},(_,i)=>from+i).filter(d=>(excludePause?cycleScheduled(c,d)||tasks.some(t=>t.cycleId===c.id&&t.day===d&&t.done&&!t.extra):cycleScheduledBase(c,d))&&(!excludePause||!cyclePausedDay(c,d)||tasks.some(t=>t.cycleId===c.id&&t.day===d&&t.done&&!t.extra))).length;
 const rawFirst=dayOf(anchorMonth(c.origin,c.index)),rawLast=dayOf(anchorMonth(c.origin,c.index+1));
 const planned=Math.max(0,c.index===0&&c.seedPlanned!==undefined?c.seedPlanned+plannedCount(first,last,true)-plannedCount(rawFirst,rawLast,false):plannedCount(first,last,true));
 const completed=(c.index===0?c.seedCompleted||0:0)+tasks.filter(t=>t.cycleId===c.id&&t.done&&t.day>=first&&t.day<last).length;
 const rate=planned>0?Math.min(completed/planned,1):null,qualified=rate!==null&&rate>=.8,factor=1.1**Math.floor(c.qualified/3),after=c.qualified+(qualified?1:0);
 return {key:`${c.id}:${start}:${end}`,cycleId:c.id,title:c.title,start,end,planned,completed,rate,before:c.qualified,after,factor:qualified?factor:1,nextFactor:1.1**Math.floor(after/3),xp:rate===null?0:Math.floor(10*rate*(qualified?factor:1))};
}
