function dateAt(day:number){const d=new Date(2026,9,18+day);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dayOf(value:string){const parts=value.split('-').map(Number);return Math.round((Date.UTC(parts[0],parts[1]-1,parts[2])-Date.UTC(2026,9,18))/86400000)}
function shortDate(day:number){return new Date(2026,9,18+day).toLocaleDateString('zh-CN',{month:'long',day:'numeric'})}
const weekdayNames=['日','一','二','三','四','五','六']
function plannedDays(start:number,end:number|undefined,cadence:'daily'|'weekly',weekdays:number[]){if(!Number.isFinite(start))return [];return Array.from({length:28},(_,i)=>start+i).filter(day=>(end===undefined||day<=end)&&(cadence==='daily'||weekdays.includes(new Date(2026,9,18+day).getDay())))}
function levelOf(xp:number) { let level=1,remaining=xp; while(remaining>=20+5*(level-1)){remaining-=20+5*(level-1);level++} return {level,remaining,required:20+5*(level-1)} }
