 const [editName,setEditName]=useState(''),[editStandard,setEditStandard]=useState(''),[editError,setEditError]=useState('')
 function openEditor(kind:'main'|'side'|'goal',id:number){
  const item=kind==='main'?mainlines.find(m=>m.id===id):kind==='side'?sides.find(q=>q.id===id):goals.find(g=>g.id===id);
  if(!item)return;
  if(kind==='goal'&&!canEditGoal(item as Goal)){setNotice('此目标只供回看，不能编辑。');return}
  if(kind==='side'&&((item as SideQuest).state!=='open'||goals.find(g=>g.id===(item as SideQuest).goalId)?.done)){setNotice('历史支线只供回看。');return}
  setEditing({kind,id});setEditName(kind==='goal'?(item as Goal).title:(item as Mainline).name);setEditStandard(kind==='goal'?(item as Goal).standard:'');setEditError('');setDetail(null);setNotice('');
 }
 function saveEditor(){
  if(!editing)return;const name=editName.trim();if(!name){setEditError('名称不能为空。');return}
  const {kind,id}=editing;
  if(kind==='main'){
   if(!mainlines.some(m=>m.id===id&&!m.archived)){setEditError('主线已不存在。');return}
   if(mainlines.some(m=>m.id!==id&&m.name===name)){setEditError('已有同名主线，请换一个名称。');return}
   setMainlines(mainlines.map(m=>m.id===id?{...m,name}:m));setGoals(goals.map(g=>g.mainId===id?{...g,field:name}:g));
  }else if(kind==='side'){
   const side=sides.find(q=>q.id===id);if(!side||side.state!=='open'||goals.find(g=>g.id===side.goalId)?.done){setEditError('该支线已转为历史记录，不能编辑。');return}
   setSides(sides.map(q=>q.id===id?{...q,name}:q));setGoals(goals.map(g=>g.sideId===id?{...g,field:name}:g));
  }else{
   const goal=goals.find(g=>g.id===id);if(!goal||!canEditGoal(goal)){setEditError('目标当前只供回看，原记录未改变。');return}
   if(!editStandard.trim()){setEditError('请填写完成标准。');return}
   setGoals(goals.map(g=>g.id===id?{...g,title:name,standard:editStandard.trim()}:g));
  }
  setEditing(null);setNotice('修改已保存，归属、任务、聚焦与成长积累均保留。');
 }
