 function isArchived(g:Goal){return !!g.archived||mainlines.some(m=>m.id===g.mainId&&m.archived)||sides.some(q=>q.id===g.sideId&&q.state!=='open')}
 function isContinuedTask(t:Task){return !!t.repeat&&mainCycles.some(c=>c.id===t.cycleId&&c.continueAfterGoal)}
 function canUseTask(t:Task|undefined){if(!t)return false;const g=goals.find(g=>g.id===t.goal);return !!g&&!isArchived(g)&&g.pending===undefined&&(!g.done||isContinuedTask(t))}
 function canManageCycle(c:MainCycle){const g=goals.find(g=>g.id===c.goal);return !!g&&!isArchived(g)&&g.pending===undefined&&(!g.done||c.continueAfterGoal===true)}
